def apply_coupon(conn, user_id: int, code: str) -> dict:
    with conn.transaction():
        coupon = conn.execute(
            """SELECT code FROM coupons
               WHERE code = %s AND active AND (expires_at IS NULL OR expires_at > now())""",
            (code,),
        ).fetchone()
        if coupon is None:
            raise ShopError("invalid_coupon")
        cart = open_cart(conn, user_id)
        if cart is None:
            raise ShopError("empty_cart")
        used = conn.execute(
            "SELECT 1 FROM coupon_redemptions WHERE coupon_code = %s AND user_id = %s AND NOT released",
            (code, user_id),
        ).fetchone()
        if used is not None:
            raise ShopError("coupon_already_used")
        conn.execute("UPDATE carts SET coupon_code = %s WHERE id = %s", (code, cart["id"]))
        conn.execute("UPDATE coupons SET active = false WHERE code = %s", (code,))
        return {"cart_id": cart["id"], "coupon_code": code}

def cancel_order(conn, user_id: int, order_id: int) -> dict:
    with conn.transaction():
        order = conn.execute(
            "SELECT * FROM orders WHERE id = %s AND user_id = %s FOR UPDATE",
            (order_id, user_id),
        ).fetchone()
        if order is None:
            raise ShopError("not_found")
        if order["status"] != "placed":
            raise ShopError("not_cancellable")
        conn.execute("UPDATE orders SET status = 'cancelled' WHERE id = %s", (order_id,))
        conn.execute(
            "UPDATE coupon_redemptions SET released = true WHERE order_id = %s AND NOT released",
            (order_id,),
        )
        emit(conn, "order.cancelled", {"order_id": order_id, "user_id": user_id})
        return {"order_id": order_id, "status": "cancelled"}

